customize.css:
.wrap{max-width:80rem;padding:0 2rem 3rem}
header.site{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:1rem 1.5rem;min-height:5.5rem;margin:0 0 2rem;padding:1rem 0;border-bottom:1px solid var(--rule);font:700 .9rem/1.25 system-ui,sans-serif}
header.site .brand{color:var(--fg);font-size:1.25rem;font-weight:800;letter-spacing:.01em;text-decoration:none}
header.site nav{display:flex;align-items:center;flex-wrap:wrap;gap:.4rem 1.1rem}
header.site nav a{margin:0;color:var(--fg);font-size:.85rem;font-weight:700;letter-spacing:.025em;text-decoration:none;text-transform:uppercase}
header.site nav a:hover{color:var(--link)}
header.site nav a:nth-last-child(2),header.site nav a:nth-last-child(3){padding:.55rem .85rem;border:2px solid var(--link);color:var(--link)}
header.site nav a:nth-last-child(2):hover,header.site nav a:nth-last-child(3):hover{background:var(--link);color:var(--bg)}
header.site nav a:last-child{color:var(--muted);font-size:.75rem;font-weight:500;text-transform:none}
h1,h2,h3,h4{font-family:var(--heading-font)}
h1{font-size:clamp(2rem,4.5vw,3.5rem);line-height:1.12}
h2{font-size:clamp(1.5rem,2.6vw,2.1rem);line-height:1.2;margin:2.25rem 0 .8rem}
h3{font-size:1.25rem;line-height:1.3}
main a{color:var(--link)}
main img{border-radius:0}
footer.site{margin-top:4rem;padding:1.5rem 0;border-top:1px solid var(--rule);font:.9rem/1.6 system-ui,sans-serif}
@media(max-width:700px){.wrap{padding:0 1rem 2.5rem}header.site{align-items:flex-start;gap:1rem}header.site nav{gap:.45rem .8rem}header.site nav a{font-size:.75rem}header.site nav a:nth-last-child(2),header.site nav a:nth-last-child(3){padding:.4rem .6rem}}
